  "Quick Change (1990)":{"fmt":"getawaysupper","brand":"Dinner before the getaway","phoneTitle":"Quick Change","tag":"The bank job was easy. Leaving New York is hard.","art":{"identity":"/fL29qQX4I2sbULfHUbMLbwwlBak.jpg","bank":"/xd7GlVVQ53P53LN9bD6yHiF52cA.jpg","detour":"/mjZnGUPYE76Nd5ih2yiVrOfiv6M.jpg"},"groups":[{"h":"The disguise","tab":"Snacks","items":[{"k":"Clown nose cherry tomatoes","c":"s","d":"Cherry tomatoes filled with basil & lemon whipped feta.","note":"A red nose for every guest. Grimm would approve."},{"k":"Airport bar peanuts","c":"s","d":"Butter-roasted peanuts, chilli & smoked paprika.","note":"So close to getting out of the city."}]},{"h":"A city that won’t let you leave","tab":"Main","items":[{"k":"Bodega sandwiches","c":"m","d":"Turkey & Swiss kaiser rolls with lettuce, tomato, mayo and mustard, wrapped tight in paper.","note":"A New York meal between wrong turns."}]},{"h":"One last red nose","tab":"Dessert","items":[{"k":"Clown cake","c":"w","d":"Jam sponge, white buttercream, a piped clown face & cherry nose.","note":"Grimm’s disguise, served by the slice."}]},{"h":"Wheels up, finally","tab":"Drink","items":[{"k":"Airport beer","c":"d","d":"Cold lager in plastic cups. A toast to leaving New York.","note":"Before anything else goes wrong."}]}]},
