  const supper=`<section aria-label="A Bronx Tale neighbourhood supper menu" style="${at(466,25,579,`height:692px;background:${R};border:1px solid #8c6d48;box-shadow:0 5px 0 #1b1010,4px 9px 16px rgba(0,0,0,.4);color:${I}`)}"><div aria-hidden="true" style="position:absolute;left:13px;top:13px;right:13px;bottom:13px;border:1px solid #694937;pointer-events:none"></div><div aria-hidden="true" style="position:absolute;left:0;top:0;bottom:0;width:13px;background:linear-gradient(90deg,rgba(0,0,0,.35),transparent)"></div><header style="${at(31,30,505)}"><div style="display:flex;justify-content:space-between">${micro('The neighbourhood supper')}${micro('Four at the table')}</div><h2 style="${H};font-size:54px;line-height:.89;letter-spacing:-.035em;font-weight:500;color:${P};margin:14px 0 0">Sunday<br><i>on the block.</i></h2><div style="margin-top:16px">${micro('The Bronx / A tale of two tables',M)}</div></header>${rows}<footer style="${at(31,662,505,'border-top:1px solid #785346;padding-top:9px;display:flex;gap:13px;align-items:baseline')}"><span style="${T};font-size:10px;color:${G};font-weight:700;letter-spacing:.04em;white-space:nowrap">AFTER DINNER</span><span style="${B};font-size:10px;line-height:1.4;color:${M}">${ESC(fmtCue(f))}</span></footer></section>`;
  return `<div class="fx-wall" style="position:relative;width:1071px;height:742px;background:${W};box-shadow:0 18px 45px rgba(0,0,0,.5)"><div aria-hidden="true" style="position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 89px,rgba(0,0,0,.16) 89px 91px),linear-gradient(120deg,rgba(153,105,52,.12),transparent 55%,rgba(0,0,0,.22))"></div>${memories}${supper}<div style="${at(26,727,1018,`${T};font-size:7px;line-height:1;color:#ac9776;letter-spacing:.08em;text-align:right`)}">A BRONX TALE / 1993 / FILM IMAGERY: TMDB</div></div>`;
